:root {
  --bg: #050a0a;
  --bg-deep: #030706;
  --panel: rgba(10, 20, 19, .72);
  --panel-solid: #091210;
  --line: rgba(164, 255, 205, .12);
  --line-strong: rgba(164, 255, 205, .22);
  --text: #edfff4;
  --muted: #80948b;
  --muted-dark: #52635c;
  --lime: #b7ff62;
  --lime-bright: #d9ff9e;
  --mint: #43f1b2;
  --mint-soft: #7bffd1;
  --coral: #ff6e51;
  --gold: #ffd35c;
  --mono: "IBM Plex Mono", "DejaVu Sans Mono", monospace;
  --display: "Space Grotesk", "Lato", sans-serif;
  --ease-out: cubic-bezier(.2, .8, .2, 1);
}

* { box-sizing: border-box; }
html { min-height: 100%; background: var(--bg); }
body {
  margin: 0;
  min-height: 100svh;
  color: var(--text);
  background:
    radial-gradient(ellipse 75% 55% at 50% -8%, rgba(130, 255, 140, .075), transparent 62%),
    radial-gradient(ellipse 60% 60% at 95% 65%, rgba(48, 235, 183, .05), transparent 68%),
    linear-gradient(180deg, #07100e 0%, #050a0a 48%, #030706 100%);
  font-family: var(--display);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 50;
  pointer-events: none;
  opacity: .018;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.85'/%3E%3C/svg%3E");
}
::selection { background: var(--lime); color: #07100c; }
button, a { -webkit-tap-highlight-color: transparent; }
button { font: inherit; }

.ambient {
  position: fixed;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 0;
}
.ambient-orb {
  position: absolute;
  display: block;
  border-radius: 50%;
  filter: blur(80px);
  opacity: .35;
  animation: drift 18s ease-in-out infinite alternate;
}
.orb-one {
  width: 420px;
  height: 420px;
  top: -190px;
  left: 12%;
  background: rgba(117, 255, 109, .10);
}
.orb-two {
  width: 510px;
  height: 510px;
  right: -230px;
  top: 40%;
  background: rgba(54, 239, 190, .075);
  animation-delay: -7s;
}
.orb-three {
  width: 300px;
  height: 300px;
  left: 42%;
  bottom: -210px;
  background: rgba(197, 255, 94, .045);
  animation-delay: -12s;
}
.ambient-grid {
  position: absolute;
  inset: 0;
  opacity: .35;
  background-image:
    linear-gradient(rgba(180, 255, 201, .028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(180, 255, 201, .028) 1px, transparent 1px);
  background-size: 74px 74px;
  mask-image: radial-gradient(ellipse 72% 66% at 50% 48%, black 5%, transparent 78%);
}
.ambient-noise {
  position: absolute;
  inset: 0;
  opacity: .2;
  background: repeating-linear-gradient(115deg, transparent 0 120px, rgba(120, 255, 160, .018) 120px 121px);
}
@keyframes drift {
  from { transform: translate3d(-20px, -10px, 0) scale(.96); }
  to { transform: translate3d(28px, 24px, 0) scale(1.06); }
}

.app {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  min-height: 100svh;
  padding: 0 32px;
}

/* ---------- Header ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: 1320px;
  height: 82px;
  margin: 0 auto;
  flex: 0 0 auto;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: var(--text);
  text-decoration: none;
  transition: opacity .2s ease;
}
.brand:hover { opacity: .82; }
.brand-mark {
  width: 39px;
  height: 39px;
  color: var(--lime);
  display: grid;
  place-items: center;
  filter: drop-shadow(0 0 12px rgba(183, 255, 98, .18));
}
.brand-mark svg { width: 100%; height: 100%; display: block; }
.brand-copy { display: flex; flex-direction: column; gap: 3px; }
.brand-name {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: .12em;
  line-height: .9;
}
.brand-slash { color: var(--lime); margin-left: 3px; letter-spacing: -.06em; }
.brand-sub {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .34em;
  color: var(--muted);
  line-height: 1;
}
.protocol {
  display: flex;
  align-items: center;
  gap: 15px;
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: .16em;
  color: var(--muted);
}
.protocol b { color: var(--text); font-weight: 500; }
.signal { display: inline-flex; align-items: center; gap: 7px; color: #a8c3b6; }
.signal-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 8px var(--lime);
  animation: signal-pulse 2.4s ease-in-out infinite;
}
.slash { color: var(--muted-dark); }
@keyframes signal-pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }

.top-actions { display: flex; align-items: center; gap: 9px; }
.utility-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 0 13px;
  border: 1px solid rgba(170, 255, 206, .11);
  border-radius: 8px;
  color: #a5b9ae;
  background: rgba(10, 20, 18, .38);
  cursor: pointer;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: .15em;
  transition: color .2s ease, border-color .2s ease, background .2s ease, transform .18s ease;
}
.utility-btn:hover {
  color: var(--text);
  border-color: rgba(183, 255, 98, .28);
  background: rgba(21, 38, 31, .6);
  transform: translateY(-1px);
}
.utility-btn:active { transform: translateY(0); }
.utility-icon { color: var(--lime); font-size: 12px; line-height: 1; }
.sound-icon { display: grid; place-items: center; color: var(--lime); }
.sound-icon svg { width: 15px; height: 15px; display: block; }
.sound-icon .icon-off { display: none; }
.sound-btn.is-muted .icon-on { display: none; }
.sound-btn.is-muted .icon-off { display: block; }
.sound-btn.is-muted .sound-icon { color: var(--muted); }
.sound-btn.is-muted .utility-label { color: var(--muted); }

/* ---------- Main layout ---------- */
.shell {
  display: grid;
  grid-template-columns: 216px minmax(0, 620px) 216px;
  justify-content: center;
  align-items: center;
  gap: clamp(20px, 2.6vw, 38px);
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
  flex: 1 1 auto;
  min-height: 0;
}
.arena {
  width: 100%;
  max-width: min(620px, calc(100svh - 216px));
  margin: 0 auto;
  align-self: center;
}
.stage-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 3px 10px;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: .2em;
  color: var(--muted);
}
.stage-label { display: inline-flex; align-items: center; gap: 8px; }
.stage-label #statusLabel { color: #b7c9bd; }
.stage-label #statusLabel.is-live { color: var(--lime); }
.stage-label #statusLabel.is-danger { color: var(--coral); }
.live-pip {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 6px rgba(183, 255, 98, .75);
}
.mini-slash { color: var(--muted-dark); }
.stage-grid-label { display: inline-flex; gap: 8px; }
.stage-grid-label span { color: #c9e0d3; }

.frame-wrap {
  position: relative;
  padding: 5px;
  border-radius: 22px;
  background: linear-gradient(145deg, rgba(183, 255, 98, .27), rgba(170, 255, 206, .06) 27%, rgba(106, 255, 164, .035) 70%, rgba(183, 255, 98, .13));
  box-shadow:
    0 42px 100px -30px rgba(0, 0, 0, .9),
    0 0 0 1px rgba(183, 255, 98, .04),
    0 0 55px -12px rgba(100, 255, 137, .10);
}
.frame-wrap::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: 23px;
  pointer-events: none;
  box-shadow: 0 0 36px rgba(130, 255, 150, .045);
}
.game-frame {
  position: relative;
  aspect-ratio: 1 / 1;
  width: 100%;
  overflow: hidden;
  border-radius: 18px;
  background: #040b09;
  isolation: isolate;
  touch-action: none;
}
#gameCanvas {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 18px;
}
.screen-glare {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  border-radius: 18px;
  background:
    radial-gradient(ellipse 60% 38% at 18% 0%, rgba(215, 255, 225, .075), transparent 70%),
    linear-gradient(135deg, rgba(255, 255, 255, .025), transparent 30%);
  mix-blend-mode: screen;
}
.scanlines {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  border-radius: 18px;
  opacity: .18;
  background: repeating-linear-gradient(to bottom, rgba(210, 255, 225, .075) 0, rgba(210, 255, 225, .075) 1px, transparent 1px, transparent 4px);
  mix-blend-mode: overlay;
}
.frame-corners { position: absolute; inset: 13px; z-index: 3; pointer-events: none; }
.frame-corners i {
  position: absolute;
  width: 15px;
  height: 15px;
  border-color: rgba(183, 255, 98, .42);
  border-style: solid;
}
.frame-corners i:nth-child(1) { top: 0; left: 0; border-width: 1px 0 0 1px; }
.frame-corners i:nth-child(2) { top: 0; right: 0; border-width: 1px 1px 0 0; }
.frame-corners i:nth-child(3) { bottom: 0; left: 0; border-width: 0 0 1px 1px; }
.frame-corners i:nth-child(4) { bottom: 0; right: 0; border-width: 0 1px 1px 0; }

/* ---------- Screen overlays ---------- */
.screen-overlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  transition: opacity .35s var(--ease-out), visibility .35s;
}
.screen-overlay.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.start-screen {
  align-items: center;
  padding: clamp(22px, 5.4%, 42px);
  background:
    linear-gradient(90deg, rgba(4, 11, 9, .97) 0%, rgba(4, 11, 9, .88) 36%, rgba(4, 11, 9, .45) 65%, rgba(4, 11, 9, .12) 100%),
    linear-gradient(0deg, rgba(4, 11, 9, .7), transparent 38%);
}
.start-index {
  position: absolute;
  top: 14px;
  right: 25px;
  font-family: var(--mono);
  font-size: 42px;
  line-height: 1;
  font-weight: 400;
  letter-spacing: -.06em;
  color: rgba(183, 255, 98, .10);
  -webkit-text-stroke: 1px rgba(183, 255, 98, .2);
}
.hero-copy { position: relative; z-index: 2; width: min(100%, 375px); }
.hero-kicker {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: clamp(15px, 2.8vh, 24px);
  font-family: var(--mono);
  font-size: clamp(7px, .58vw, 9px);
  font-weight: 500;
  letter-spacing: .19em;
  color: #8ca59a;
}
.hero-kicker b { color: rgba(183, 255, 98, .7); font-weight: 400; }
.kicker-line {
  width: 23px;
  height: 1px;
  background: var(--lime);
  box-shadow: 0 0 8px rgba(183, 255, 98, .4);
}
.hero-copy h1 {
  margin: 0;
  display: flex;
  flex-direction: column;
  font-size: clamp(52px, 5.6vw, 81px);
  font-weight: 700;
  line-height: .82;
  letter-spacing: -.075em;
  color: #effff4;
  text-shadow: 0 2px 30px rgba(0, 0, 0, .35);
}
.hero-copy h1 .accent {
  width: fit-content;
  background: linear-gradient(96deg, #e4ffa9 0%, #b7ff62 37%, #63ff9e 72%, #34e9b3 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 22px rgba(123, 255, 127, .18));
  padding-bottom: .08em;
}
.hero-tagline {
  margin: clamp(16px, 2.8vh, 23px) 0 0;
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 10px);
  font-weight: 600;
  letter-spacing: .24em;
  color: #c8e2d4;
}
.hero-desc {
  max-width: 285px;
  margin: 12px 0 0;
  font-size: clamp(11px, .89vw, 13px);
  line-height: 1.62;
  color: #8da095;
}
.hero-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 13px;
  margin-top: clamp(20px, 3.5vh, 31px);
}
.primary-btn {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  min-height: 50px;
  padding: 0 14px 0 9px;
  border: 1px solid rgba(218, 255, 165, .4);
  border-radius: 10px;
  background: linear-gradient(100deg, #c9ff7a 0%, #a1ff5d 52%, #7cf59a 100%);
  color: #0a170e;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .14em;
  cursor: pointer;
  box-shadow: 0 10px 30px -12px rgba(160, 255, 93, .55), inset 0 1px 0 rgba(255, 255, 255, .45);
  transition: transform .2s var(--ease-out), box-shadow .2s ease, filter .2s ease;
}
.primary-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 42px -12px rgba(160, 255, 93, .62), inset 0 1px 0 rgba(255, 255, 255, .55);
  filter: brightness(1.04);
}
.primary-btn:active { transform: translateY(0); }
.btn-play {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 7px;
  background: rgba(5, 22, 10, .11);
  border: 1px solid rgba(7, 29, 13, .15);
}
.btn-play svg { width: 17px; height: 17px; }
.btn-key {
  display: grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  margin-left: 3px;
  padding: 0 6px;
  border: 1px solid rgba(8, 30, 14, .19);
  border-radius: 5px;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  color: rgba(8, 30, 15, .62);
  background: rgba(255, 255, 255, .16);
}
.text-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 2px 0;
  border: 0;
  border-bottom: 1px solid transparent;
  background: transparent;
  color: #8ea297;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: .16em;
  cursor: pointer;
  transition: color .2s ease, border-color .2s ease;
}
.text-btn span { color: var(--lime); font-size: 10px; transition: transform .2s ease; }
.text-btn:hover { color: #d5e9dd; border-bottom-color: rgba(183, 255, 98, .35); }
.text-btn:hover span { transform: translate(1px, -1px); }
.hero-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 11px;
  margin-top: clamp(22px, 3.6vh, 32px);
  padding-top: 14px;
  border-top: 1px solid rgba(168, 255, 202, .11);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .13em;
  color: #71877b;
}
.hero-meta b { color: #b5cbbd; font-weight: 500; }
.meta-sep { color: #41534a; }
.mobile-only { display: none; }
.hero-badge {
  position: absolute;
  right: 25px;
  bottom: 25px;
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .14em;
  color: rgba(163, 192, 175, .53);
}
.hero-badge b { color: var(--lime); font-size: 10px; font-weight: 500; }
.hero-badge i { width: 3px; height: 3px; border-radius: 50%; background: var(--lime); opacity: .6; }

.pause-screen,
.gameover-screen {
  align-items: center;
  justify-content: center;
  padding: 26px;
  background: rgba(3, 9, 7, .66);
  backdrop-filter: blur(7px) saturate(.8);
  -webkit-backdrop-filter: blur(7px) saturate(.8);
}
.modal-panel {
  width: min(100%, 365px);
  padding: clamp(21px, 4vw, 31px);
  border: 1px solid rgba(178, 255, 207, .16);
  border-radius: 15px;
  background:
    linear-gradient(155deg, rgba(17, 32, 27, .91), rgba(6, 14, 12, .94)),
    radial-gradient(circle at 100% 0, rgba(183, 255, 98, .08), transparent 55%);
  box-shadow: 0 30px 70px rgba(0, 0, 0, .55), inset 0 1px 0 rgba(255, 255, 255, .035);
}
.modal-panel .panel-kicker { margin-bottom: 20px; }
.panel-kicker.danger span:first-child { color: #ff9e88; }
.panel-kicker.danger .panel-index { color: var(--coral); border-color: rgba(255, 110, 81, .22); }
.overlay-title {
  margin: 0;
  font-size: clamp(44px, 5vw, 61px);
  font-weight: 700;
  line-height: .86;
  letter-spacing: -.065em;
}
.overlay-sub {
  margin: 14px 0 0;
  font-size: 12px;
  color: #8ba094;
  line-height: 1.5;
}
.overlay-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px;
  margin-top: 23px;
}
.compact-primary { min-height: 45px; padding-right: 9px; font-size: 9px; }
.overlay-hint {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid rgba(168, 255, 202, .09);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .06em;
  color: #697e72;
}
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border: 1px solid rgba(177, 244, 202, .19);
  border-bottom-color: rgba(177, 244, 202, .1);
  border-radius: 4px;
  background: rgba(173, 255, 203, .045);
  box-shadow: 0 1px 0 rgba(0, 0, 0, .3);
  font-family: var(--mono);
  font-size: 8px;
  color: #a4bbae;
}

.gameover-title { color: #effff4; line-height: .8; }
.gameover-title span {
  color: transparent;
  -webkit-text-stroke: 1.2px rgba(255, 110, 81, .9);
  filter: drop-shadow(0 0 17px rgba(255, 110, 81, .18));
}
.new-record {
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin-bottom: 14px;
  color: var(--gold);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 500;
  letter-spacing: .14em;
}
.new-record span { width: 3px; height: 3px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 7px var(--gold); }
.new-record.hidden { display: none; }
.final-score {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-top: 20px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(170, 255, 202, .11);
}
.final-score span {
  padding-bottom: 4px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .13em;
  color: #71867a;
}
.final-score strong {
  font-family: var(--mono);
  font-size: clamp(28px, 3.2vw, 36px);
  font-weight: 500;
  line-height: .8;
  letter-spacing: -.06em;
  color: var(--lime);
  text-shadow: 0 0 20px rgba(183, 255, 98, .2);
}
.final-stats { display: flex; gap: 26px; margin-top: 14px; }
.final-stats div { display: flex; flex-direction: column; gap: 4px; }
.final-stats span {
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: .13em;
  color: #6b8074;
}
.final-stats b { font-family: var(--mono); font-size: 12px; font-weight: 500; color: #c3d7ca; }

.event-toast {
  position: absolute;
  top: 20px;
  left: 50%;
  z-index: 4;
  transform: translate(-50%, -10px);
  opacity: 0;
  pointer-events: none;
  padding: 8px 12px;
  border: 1px solid rgba(183, 255, 98, .28);
  border-radius: 5px;
  background: rgba(4, 16, 10, .88);
  color: var(--lime);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: .16em;
  box-shadow: 0 5px 20px rgba(0, 0, 0, .3), 0 0 18px rgba(183, 255, 98, .08);
  transition: opacity .18s ease, transform .28s var(--ease-out);
}
.event-toast.show { opacity: 1; transform: translate(-50%, 0); }
.event-toast.gold { color: var(--gold); border-color: rgba(255, 211, 92, .3); }

/* ---------- Side panels ---------- */
.side-panel {
  position: relative;
  align-self: center;
  padding: 19px 18px;
  border: 1px solid rgba(170, 255, 204, .095);
  border-radius: 14px;
  background:
    linear-gradient(157deg, rgba(16, 29, 25, .65), rgba(5, 12, 10, .38)),
    radial-gradient(circle at 100% 0, rgba(183, 255, 98, .035), transparent 58%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .025), 0 25px 60px -40px #000;
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
}
.side-panel::after {
  content: "";
  position: absolute;
  top: 0;
  right: 18px;
  width: 26px;
  height: 1px;
  background: rgba(183, 255, 98, .5);
  box-shadow: 0 0 8px rgba(183, 255, 98, .25);
}
.panel-kicker {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--mono);
  font-size: 7.5px;
  font-weight: 500;
  letter-spacing: .17em;
  color: #72867b;
}
.panel-index {
  display: grid;
  place-items: center;
  width: 22px;
  height: 17px;
  border: 1px solid rgba(183, 255, 98, .14);
  border-radius: 3px;
  color: #91aa9c;
  font-size: 6.5px;
  letter-spacing: .02em;
}
.score-cluster { margin-top: 30px; }
.label {
  display: block;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .16em;
  color: #6d8175;
}
.score-value {
  display: block;
  margin-top: 7px;
  font-family: var(--mono);
  font-size: clamp(28px, 2.5vw, 35px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -.065em;
  color: #e9fff0;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 30px rgba(201, 255, 224, .06);
  transition: color .25s ease;
}
.score-value.pop { animation: score-pop .38s var(--ease-out); }
@keyframes score-pop {
  0% { transform: scale(1); }
  35% { transform: scale(1.055); color: var(--lime); }
  100% { transform: scale(1); }
}
.best-line {
  display: flex;
  justify-content: space-between;
  margin-top: 15px;
  padding-top: 12px;
  border-top: 1px solid rgba(170, 255, 204, .08);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: .12em;
  color: #64796d;
}
.best-line b { color: #a6bcae; font-weight: 500; letter-spacing: 0; }
.rule { height: 1px; margin: 20px 0; background: linear-gradient(90deg, rgba(171, 255, 201, .14), transparent); }
.stat-row + .stat-row { margin-top: 17px; }
.stat-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 7px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .14em;
  color: #6d8175;
}
.stat-head b { color: #bfd5c7; font-size: 9px; font-weight: 500; letter-spacing: 0; }
.meter {
  position: relative;
  height: 3px;
  overflow: hidden;
  border-radius: 3px;
  background: rgba(165, 255, 200, .08);
}
.meter span {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, #4eebac, #b7ff62);
  box-shadow: 0 0 9px rgba(130, 255, 120, .35);
  transition: width .35s ease;
}
.meter-alt span { background: linear-gradient(90deg, #ffcc58, #ff8c54); box-shadow: 0 0 9px rgba(255, 174, 75, .3); }
.sector-card {
  margin-top: 22px;
  padding: 11px 10px 9px;
  border: 1px solid rgba(170, 255, 202, .075);
  border-radius: 7px;
  background: rgba(4, 12, 9, .36);
}
.sector-head {
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: .15em;
  color: #6a7f72;
}
.sector-head b { color: var(--lime); font-weight: 500; }
.sector-map {
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  gap: 3px;
  margin: 9px 0 8px;
}
.sector-map i { display: block; height: 5px; background: rgba(154, 255, 178, .1); border-radius: 1px; }
.sector-map i:nth-child(2),
.sector-map i:nth-child(4),
.sector-map i:nth-child(5),
.sector-map i:nth-child(8) { background: rgba(183, 255, 98, .8); box-shadow: 0 0 5px rgba(183, 255, 98, .45); }
.sector-map i:nth-child(3) { background: rgba(183, 255, 98, .18); }
.sector-foot { font-family: var(--mono); font-size: 5.5px; letter-spacing: .08em; color: #53665b; }
.panel-note {
  margin: 20px 0 0;
  font-size: 9.5px;
  line-height: 1.5;
  color: #65786d;
}

.objective {
  display: flex;
  gap: 11px;
  margin-top: 22px;
  padding-bottom: 19px;
  border-bottom: 1px solid rgba(170, 255, 204, .08);
}
.objective-no {
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  flex: 0 0 auto;
  border: 1px solid rgba(183, 255, 98, .25);
  border-radius: 50%;
  color: var(--lime);
  font-family: var(--mono);
  font-size: 7px;
}
.objective p { margin: 0; font-size: 10px; line-height: 1.55; color: #91a69a; }
.legend { display: flex; flex-direction: column; gap: 15px; margin-top: 20px; }
.legend-item { display: flex; align-items: center; gap: 11px; }
.legend-item div { display: flex; flex-direction: column; gap: 3px; }
.legend-item b { font-family: var(--mono); font-size: 6.8px; font-weight: 500; letter-spacing: .13em; color: #b4c9bb; }
.legend-item span { font-size: 8.5px; color: #64786c; }
.node-icon {
  position: relative;
  display: block;
  width: 19px;
  height: 19px;
  flex: 0 0 auto;
  border-radius: 50%;
  border: 1px solid rgba(183, 255, 98, .45);
  box-shadow: 0 0 12px rgba(183, 255, 98, .12), inset 0 0 8px rgba(183, 255, 98, .2);
}
.node-normal::after {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 6px var(--lime);
}
.node-gold { border-color: rgba(255, 211, 92, .52); box-shadow: 0 0 12px rgba(255, 211, 92, .13), inset 0 0 8px rgba(255, 211, 92, .18); }
.node-gold::after {
  content: "";
  position: absolute;
  inset: 5px;
  transform: rotate(45deg);
  background: var(--gold);
  box-shadow: 0 0 7px var(--gold);
}
.flow-card {
  margin-top: 23px;
  padding: 12px 11px 11px;
  border: 1px solid rgba(170, 255, 202, .09);
  border-radius: 8px;
  background: rgba(6, 15, 11, .4);
}
.flow-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: .14em;
  color: #6b8073;
}
.flow-head b { color: var(--lime); font-size: 14px; font-weight: 500; letter-spacing: -.02em; text-shadow: 0 0 12px rgba(183, 255, 98, .22); }
.flow-pips { display: flex; gap: 3px; margin-top: 9px; }
.flow-pips i { display: block; height: 3px; flex: 1; border-radius: 1px; background: rgba(170, 255, 200, .1); transition: background .2s ease, box-shadow .2s ease; }
.flow-pips i.active { background: var(--lime); box-shadow: 0 0 6px rgba(183, 255, 98, .38); }
.flow-track { height: 2px; margin-top: 9px; overflow: hidden; border-radius: 2px; background: rgba(170, 255, 200, .07); }
.flow-track span { display: block; width: 0; height: 100%; background: linear-gradient(90deg, #4cebb0, #d8ff88); }
.flow-card p { margin: 9px 0 0; font-size: 8.5px; line-height: 1.45; color: #62766a; }
.flow-card p b { color: #a7c0b0; font-weight: 500; }
.record-card {
  margin-top: 22px;
  padding-top: 16px;
  border-top: 1px solid rgba(170, 255, 204, .08);
}
.record-card > span { font-family: var(--mono); font-size: 6.5px; letter-spacing: .14em; color: #657a6d; }
.record-card div { display: flex; align-items: baseline; gap: 6px; margin-top: 6px; }
.record-card b { font-family: var(--mono); font-size: 18px; font-weight: 500; letter-spacing: -.03em; color: #d9eee0; }
.record-card em { font-family: var(--mono); font-size: 5.5px; letter-spacing: .13em; font-style: normal; color: #607569; }
.record-line { display: block; width: 37px; height: 1px; margin-top: 10px; background: var(--lime); opacity: .45; }
.tip-note { display: flex; gap: 7px; }
.tip-note span { color: var(--lime); }

.stage-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 11px 3px 0;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .08em;
  color: #61756a;
}
.key-hints, .key-group { display: flex; align-items: center; }
.key-hints { gap: 15px; }
.key-group { gap: 3px; }
.key-group em { font-style: normal; margin-left: 3px; font-size: 6.5px; letter-spacing: .13em; color: #596d61; }
.key-group kbd { min-width: 16px; height: 16px; padding: 0 3px; font-size: 7px; color: #83998c; }
.stage-tag { font-size: 6.5px; letter-spacing: .13em; color: #4c6055; }
.stage-tag b { color: #6e8578; font-weight: 400; }

.compact-hud { display: none; }

/* ---------- Touch controls ---------- */
.touch-controls { display: none; }
.app-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  max-width: 1320px;
  height: 46px;
  margin: 0 auto;
  flex: 0 0 auto;
  border-top: 1px solid rgba(170, 255, 202, .065);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: .14em;
  color: #52655b;
}
.app-footer b { color: rgba(183, 255, 98, .48); font-weight: 400; }
.footer-center { display: inline-flex; align-items: center; gap: 9px; color: #41534a; }
.footer-center i { width: 3px; height: 3px; border-radius: 50%; background: rgba(183, 255, 98, .42); }

/* ---------- Help modal ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: grid;
  place-items: center;
  padding: 22px;
  background: rgba(2, 7, 5, .75);
  backdrop-filter: blur(11px);
  -webkit-backdrop-filter: blur(11px);
  transition: opacity .25s ease, visibility .25s;
}
.modal-backdrop.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.help-modal {
  position: relative;
