import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
const browser = await chromium.launch({ headless: true })

async function shot(name, w, h, wait) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', (e) => errors.push(e.message))
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()) })
  await page.goto('http://localhost:3002/?debug=1', { waitUntil: 'networkidle' })
  await page.waitForFunction(() => document.fonts.status === 'loaded')
  await page.waitForTimeout(400)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(wait)
  const info = await page.evaluate(() => {
    const s = window.__serpentDebug.state
    return { mode: s.mode, score: s.score, len: s.snake.length, flow: s.streak, popups: s.popups.length }
  })
  await page.screenshot({ path: join(out, name + '.jpg'), type: 'jpeg', quality: 82 })
  console.log(name, JSON.stringify(info), errors.length ? 'ERRORS: ' + errors.join(' | ') : 'ok')
  await page.close()
}

await shot('final-mobile-game', 390, 844, 2400)
await shot('final-landscape-game', 844, 390, 2400)
await shot('final-tablet-game', 768, 1024, 2400)
await browser.close()

import { createRequire } from 'node:module'
