const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const browser = await chromium.launch({ headless: true })
const sizes = [[1280, 900], [1280, 720], [1024, 768], [768, 1024], [390, 844], [360, 640], [320, 568], [844, 390]]
for (const [w, h] of sizes) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', (e) => errors.push(e.message))
  await page.goto('http://localhost:3002/?debug=1', { waitUntil: 'networkidle' })
  await page.waitForFunction(() => document.fonts.status === 'loaded')
  await page.waitForTimeout(250)
  const r = await page.evaluate(() => {
    const de = document.documentElement
    const start = document.querySelector('#startBtn').getBoundingClientRect()
    const frame = document.querySelector('.frame-wrap').getBoundingClientRect()
    const left = document.querySelector('.panel-left')
    const right = document.querySelector('.panel-right')
    const p = (el) => el ? { top: +el.getBoundingClientRect().top.toFixed(1), height: +el.getBoundingClientRect().height.toFixed(1) } : null
    return {
      scrollW: de.scrollWidth, scrollH: de.scrollHeight,
      startVisible: start.top >= 0 && start.bottom <= innerHeight && start.left >= 0 && start.right <= innerWidth,
      start: { top: +start.top.toFixed(1), bottom: +start.bottom.toFixed(1), left: +start.left.toFixed(1), right: +start.right.toFixed(1) },
      frame: { top: +frame.top.toFixed(1), bottom: +frame.bottom.toFixed(1), w: +frame.width.toFixed(1), h: +frame.height.toFixed(1) },
      left: p(left), right: p(right),
    }
  })
  const overflow = r.scrollW > w || r.scrollH > h
  console.log(`${w}x${h}`, overflow ? 'OVERFLOW' : 'fits', `scroll ${r.scrollW}x${r.scrollH}`, 'startVis', r.startVisible, 'frame', JSON.stringify(r.frame), r.left ? `left ${r.left.height}@${r.left.top} right ${r.right.height}@${r.right.top}` : '', errors.length ? 'JSERR ' + errors.join('|') : '')
  await page.close()
}
await browser.close()

